int aq_nic_set_media_detect ( struct aq_nic_s * self , int val ) { struct aq_nic_cfg_s * cfg = & self -> aq_nic_cfg ; int err = 0 ; if ( val > 0 && val != AQ_HW_MEDIA_DETECT_CNT ) { netdev_err ( self -> ndev , "EDPD on this device could have only fixed value of %d\n" , AQ_HW_MEDIA_DETECT_CNT ) ; return - EINVAL ; } mutex_lock ( & self -> fwreq_mutex ) ; err = self -> aq_fw_ops -> set_media_detect ( self -> aq_hw , ! ! val ) ; mutex_unlock ( & self -> fwreq_mutex ) ; if ( ! err ) { cfg -> is_media_detect = ! ! val ; } return err ; } 